}

::-webkit-scrollbar-thumb:hover {
background: var(--glass-border);
}

@media (max-width: 768px) {
.sidebar {
display: none;
}
header {
padding: 0 15px;
}
.chat-container {
padding: 15px;
}
.message-bubble {
max-width: 85%;
}
.grid {
grid-template-columns: 1fr;
padding: 15px;
}
}
</style>
</head>
